$bt=static fn(string $text):string=>\Kulturhus\Native\Language\FinanceBankMessages::text($text,$invoicebankMessages);
$bv=static fn(mixed $value):string=>is_string($value)||is_int($value)?(string)$value:(is_bool($value)?($value?'1':'0'):(is_array($value)?GeneralRequests::json($value):''));
$bkeep=[];foreach(['invoicebank_draft','invoicebank_receipt','invoicebank_history_q','invoicebank_history_page','invoicebank_revisions_page','invoicebank_revision','invoicebank_query','invoicebank_page']as$key)if(is_string($_GET[$key]??null))$bkeep[$key]=$_GET[$key];
$burl=static fn(array $query=[]):string=>url(['view'=>'settings','section'=>'bank']+array_replace($bkeep,$query));
$bhidden=static function(array $except=[])use($bkeep):string{$out=hidden('view','settings').hidden('section','bank');foreach($bkeep as$key=>$value)if(!in_array($key,$except,true))$out.=hidden($key,$value);return$out;};
$bvalues=static function(array $data)use($bt,$bv):void{?><details class="general-settings-values"><summary><?= e($bt('Vollständige Bankdaten')) ?></summary><dl class="general-settings-description"><?php foreach(SettingsSchema::fields('bank')as$key=>$field):?><dt><?= e($bt($field[0])) ?></dt><dd><?= nl2br(e($bv($data[$key]??''))) ?></dd><?php endforeach ?></dl><pre><?= e(GeneralRequests::json($data)) ?></pre></details><?php };
$bsource=static function(?array $source)use($bt):void{if(!$source){?><p><?= e($bt('Noch kein Rechnungskonto zugeordnet.')) ?></p><?php return;}$row=$source['account'];?><article class="general-settings-row"><p><strong><?= e($row['name']) ?></strong></p><p><code><?= e($row['id']) ?></code> · <?= e($bt(!empty($source['settings']['active'])?'Aktiv':'Inaktiv')) ?></p><details class="general-settings-values"><summary><?= e($bt('Tatsächliche geprüfte Kontendaten')) ?></summary><pre><?= e(GeneralRequests::json($source)) ?></pre></details></article><?php };
$breview=static function(array $review)use($bt,$bvalues,$bsource):void{?><h4><?= e($bt('Damals gelesener Stand')) ?> · <?= e($review['current']['version']) ?></h4><?php $bvalues($review['current']['data']);?><h4><?= e($bt('Vollständige gewünschte Eingaben')) ?></h4><?php $bvalues($review['input']['data']);?><h4><?= e($bt('Nach Bestätigung gespeicherte Werte')) ?></h4><?php $bvalues($review['normalized']);?><h4><?= e($bt('Damals geprüftes tatsächliches Rechnungskonto')) ?></h4><?php $bsource($review['bank_context']);};
$bpages=static function(?array $page,string $field)use($bt,$bhidden):void{if(!$page)return;?><form method="get" class="general-settings-page-form"><?= $bhidden([$field]) ?><label class="general-settings-field"><?= e($bt('Seite')) ?><input class="form-control" name="<?= e($field) ?>" value="<?= e($page['page_input']) ?>" inputmode="numeric"></label><button class="btn btn-outline theme-secondary"><?= e($bt('Seite öffnen')) ?></button><span><?= e($page['total']) ?> · <?= e($page['pages']) ?></span></form><?php };
?>
